import pandas as pd
import json
import numpy as np

def main():
    file_path = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

    # Read PVC sheet
    df_pvc = pd.read_excel(file_path, sheet_name="PVC")

    # Extract data columns based on the preview info
    # Col B: Temperature (°C), Col C: Weight (%), Col D: Deriv. Weight (%/°C)
    temp = df_pvc['Temperature (°C)'].values
    weight = df_pvc['Weight (%)'].values
    deriv_weight = df_pvc['Deriv. Weight (%/°C)'].values

    # Prepare data for ECharts series
    # Series 1: TGA (Weight %) - Left Y axis
    tga_data = [[float(t), float(w)] for t, w in zip(temp, weight)]

    # Series 2: DTG (Deriv. Weight) - Right Y axis
    dtg_data = [[float(t), float(dw)] for t, dw in zip(temp, deriv_weight)]

    # Chart dimensions: 10 inches wide. 
    # Height is not specified, but typically TGA plots are roughly square or slightly wider than tall.
    # Let's use a standard aspect ratio, e.g., 10x7 inches -> 960x672 px at 96 dpi.
    width_px = int(10 * 96)
    height_px = int(7 * 96)

    option = {
        "backgroundColor": "#ffffff",
        "title": {
            "text": "TGA/DTG Analysis of PVC",
            "left": "center",
            "top": "3%",
            "textStyle": {
                "fontSize": 24,
                "fontWeight": "bold",
                "fontFamily": "Noto Sans CJK KR"
            }
        },
        "tooltip": {
            "trigger": "axis",
            "axisPointer": {
                "type": "cross"
            },
            "formatter": "{a} <br/>{b}: {c}"
        },
        "legend": {
            "data": ["Weight (%)", "Deriv. Weight (%/°C)"],
            "top": "10%",
            "right": "5%",
            "textStyle": {
                "fontSize": 16,
                "fontFamily": "Noto Sans CJK KR"
            }
        },
        "grid": {
            "left": "8%",
            "right": "8%",
            "bottom": "10%",
            "top": "18%",
            "containLabel": True
        },
        "xAxis": {
            "name": "Temperature (°C)",
            "nameLocation": "middle",
            "nameGap": 35,
            "type": "value",
            "min": 30,
            "max": 900,
            "axisLabel": {
                "fontSize": 16,
                "fontFamily": "Noto Sans CJK KR"
            },
            "nameTextStyle": {
                "fontSize": 18,
                "fontFamily": "Noto Sans CJK KR"
            },
            "splitLine": {
                "show": True,
                "lineStyle": {
                    "color": "#eee"
                }
            }
        },
        "yAxis": [
            {
                "name": "Weight (%)",
                "type": "value",
                "position": "left",
                "min": 0,
                "max": 110,
                "axisLabel": {
                    "fontSize": 16,
                    "fontFamily": "Noto Sans CJK KR"
                },
                "nameTextStyle": {
                    "fontSize": 18,
                    "fontFamily": "Noto Sans CJK KR"
                },
                "splitLine": {
                    "show": True,
                    "lineStyle": {
                        "color": "#eee"
                    }
                }
            },
            {
                "name": "Deriv. Weight (%/°C)",
                "type": "value",
                "position": "right",
                "axisLabel": {
                    "fontSize": 16,
                    "fontFamily": "Noto Sans CJK KR"
                },
                "nameTextStyle": {
                    "fontSize": 18,
                    "fontFamily": "Noto Sans CJK KR"
                },
                "splitLine": {
                    "show": False
                }
            }
        ],
        "series": [
            {
                "name": "Weight (%)",
                "type": "line",
                "smooth": True,
                "symbol": "none",
                "lineStyle": {
                    "width": 3,
                    "color": "#5470c6"
                },
                "itemStyle": {
                    "color": "#5470c6"
                },
                "data": tga_data,
                "yAxisIndex": 0
            },
            {
                "name": "Deriv. Weight (%/°C)",
                "type": "line",
                "smooth": True,
                "symbol": "none",
                "lineStyle": {
                    "width": 3,
                    "color": "#ee6666"
                },
                "itemStyle": {
                    "color": "#ee6666"
                },
                "data": dtg_data,
                "yAxisIndex": 1
            }
        ]
    }

    figure = {
        "name": "pvc_tga_dtg",
        "option": option,
        "width": width_px,
        "height": height_px,
        "dpi": 300,
        "formats": ["png"]
    }

    output = {"figures": [figure]}
    print(json.dumps(output))

if __name__ == "__main__":
    main()
